import { ConvexProvider, ConvexReactClient } from "convex/react";
import { Stack } from "expo-router";
import { UserContext } from './../context/UserContext';
import { RefreshDataContext } from './../context/RefreshDataContext'
import { useState } from "react";
export default function RootLayout() {
  const convex = new ConvexReactClient(process.env.EXPO_PUBLIC_CONVEX_URL!, {
    unsavedChangesWarning: false,
  });

  const [user, setUser] = useState();
  const [refreshData, setrefreshData] = useState();
  return (
    <ConvexProvider client={convex}>
      <UserContext.Provider value={{ user, setUser }}>
        <RefreshDataContext.Provider value={{}}>
        <Stack screenOptions={{
          headerShown: false
        }}>
          <Stack.Screen name="index" />
        </Stack>
        </RefreshDataContext.Provider>
      </UserContext.Provider>
    </ConvexProvider>

  )
}

import { Platform, StyleSheet, Text, TextInput, View } from 'react-native'
import Button from '../../components/shared/Button'
import Colors from '../../shared/Colors'
import { GenerateAIRecipe } from '../../services/AiModel'
import Prompt from '../../shared/Prompt'
import { useState } from 'react'
import { TouchableOpacity } from 'react-native'
import RecipeOptionList from '../../components/RecipeOptionList'

export default function GenerateAiRecipe() {
    const [input, setInput] = useState();
    const [type, setType] = useState('Veg');
    const [loading, setLoading] = useState(false);
    const [recipeOption,setRecipeOption]=useState([]);
    const GenerateRecipeOptions = async () => {
        setLoading(true);
        // Make AI Model call to generate recipe Options
        try {
            const PROMPT = "User Input: '" + input + "'. Dietary Preference: " + type + ".\n" + Prompt.GENERATE_RECIPE_OPTION_PROMPT;
            const result = await GenerateAIRecipe(PROMPT);
            console.log(result.choices[0].message)
            const extractJson=(result.choices[0].message.content).replace('```json','').replace('```','')
            const parsedJSONResp=JSON.parse(extractJson);
            console.log(parsedJSONResp);
            setRecipeOption(parsedJSONResp);
            setLoading(false)
        }
        catch (e) {
            setLoading(false);
            console.log(e)
        }

    }
    return (
        <View style={{
            paddingTop: Platform.OS === 'ios' ? 40 : 20,
            padding: 20,
            backgroundColor: Colors.WHITE,
            height: '100%'
        }}>
            <Text style={{
                fontSize: 25,
                fontWeight: 'bold'
            }}>
                AI Recipe Generator
            </Text>

            <Text style={{
                marginTop: 10,
                fontSize: 16,
                color: Colors.GRAY
            }}>
                Generate personalized recipes using AI
            </Text>

            <TextInput
                style={styles.textarea}
                onChangeText={(value) => setInput(value)}
                placeholder='Enter your ingredient or recipe name'
                multiline={true}   // ✅ fix
            />

            <View style={{ flexDirection: 'row', gap: 10, marginTop: 15 }}>
                {['Veg', 'Non-Veg', 'Vegan'].map((item) => (
                    <TouchableOpacity key={item} onPress={() => setType(item)} style={{
                        padding: 10,
                        borderWidth: 1,
                        borderColor: type === item ? Colors.PRIMARY : Colors.GRAY,
                        borderRadius: 8,
                        backgroundColor: type === item ? Colors.PRIMARY : Colors.WHITE,
                        flex: 1,
                        alignItems: 'center'
                    }}>
                        <Text style={{color: type === item ? Colors.WHITE : Colors.GRAY, fontWeight: 'bold'}}>{item}</Text>
                    </TouchableOpacity>
                ))}
            </View>

            <View style={{
                marginTop: 25
            }}>
                <Button title={'Generate Recipe'}
                    onPress={GenerateRecipeOptions}
                    loading={loading} />
            </View>
            {recipeOption.length>0&&<RecipeOptionList recipeOption={recipeOption}/>}
        </View>
    )
}

const styles = StyleSheet.create({
    textarea: {
        padding: 15,
        borderWidth: 1,
        borderRadius: 10,
        fontSize: 20,
        marginTop: 15,
        height: 150,
        textAlignVertical: 'top',
        backgroundColor: Colors.WHITE
    }
})

import React, { useState, useEffect, useContext } from 'react';
import { Text, TouchableOpacity, View, FlatList, Alert } from 'react-native';
import Colors from '../shared/Colors';
import moment from 'moment';
import { HugeiconsIcon } from '@hugeicons/react-native';
import { Coffee02Icon, Sun03Icon, Moon02Icon } from '@hugeicons/core-free-icons';
import { UserContext } from '../context/UserContext';
import { api } from '../convex/_generated/api';
import { useMutation } from 'convex/react';
import Button from './shared/Button';

export default function AddToMealActionSheet({ recipeDetail, hideActionSheet }) {
    const [dateList, setDateList] = useState([]);
    const [selectedDate, setSelctedDate] = useState();
    const [selectedMeal, setSelctedMeal] = useState();
    const { user } = useContext(UserContext)
    const CreateMealPlan = useMutation(api.MealPlan.CreateMealPlan)
    const mealOptions = [
        {
            title: 'Breakfast',
            icon: Coffee02Icon
        },
        {
            title: 'Lunch',
            icon: Sun03Icon
        },
        {
            title: 'Dinner',
            icon: Moon02Icon
        }
    ];

    useEffect(() => {
        GenerateDates();
    }, []);

    const GenerateDates = () => {
        const result = [];

        for (let i = 0; i < 4; i++) {
            const nextDate = moment().add(i, 'days').format('DD/MM/YYYY');
            result.push(nextDate);
        }
        console.log(result);
        setDateList(result);
    };

    const AddToMealPlan = async() => {
        if (!selectedDate || !selectedMeal) {
            Alert.alert('Error!', 'Please Select All Details ')
            return;
        }
        const result = await CreateMealPlan({
            date: selectedDate,
            mealType: selectedMeal,
            recipeId: recipeDetail?._id,
            uid: user?._id
        })
        console.log(result);
        Alert.alert('Added!', 'Added to Meal Plan')
        hideActionSheet()
    }

    return (
        <View style={{ padding: 20 }}>
            <Text style={{
                fontSize: 20,
                fontWeight: 'bold',
                textAlign: 'center'
            }}>
                Add To Meal
            </Text>

            <Text style={{
                fontSize: 18,
                fontWeight: 'bold',
                marginTop: 15
            }}>
                Select Date
            </Text>

            <FlatList
                data={dateList}
                numColumns={4}
                keyExtractor={(item, index) => index.toString()}
                renderItem={({ item }) => (
                    <TouchableOpacity
                        onPress={() => setSelctedDate(item)}
                        style={{
                            flex: 1,
                            alignItems: 'center',
                            padding: 7,
                            borderWidth: 1,
                            borderRadius: 10,
                            margin: 5,
                            backgroundColor: selectedDate == item ? Colors.SECONDERY : Colors.WHITE,
                            borderColor: selectedDate == item ? Colors.PRIMARY : Colors.GRAY
                        }}>
                        <Text style={{ fontSize: 18, fontWeight: '500' }}>
                            {moment(item, 'DD/MM/YYYY').format('ddd')}
                        </Text>
                        <Text style={{ fontSize: 20, fontWeight: 'bold' }}>
                            {moment(item, 'DD/MM/YYYY').format('DD')}
                        </Text>
                        <Text style={{ fontSize: 16 }}>
                            {moment(item, 'DD/MM/YYYY').format('MMM')}
                        </Text>
                    </TouchableOpacity>
                )}
            />

            <FlatList
                data={mealOptions}
                numColumns={3}
                keyExtractor={(item, index) => index.toString()}
                renderItem={({ item }) => (
                    <TouchableOpacity
                        onPress={() => setSelctedMeal(item.title)}
                        style={{
                            flex: 1,
                            alignItems: 'center',
                            padding: 7,
                            borderWidth: 1,
                            borderRadius: 10,
                            margin: 5,
                            backgroundColor: selectedMeal == item.title ? Colors.SECONDERY : Colors.WHITE,
                            borderColor: selectedMeal == item.title ? Colors.PRIMARY : Colors.GRAY
                        }}>

                        <HugeiconsIcon icon={item.icon} />

                        <Text style={{
                            fontSize: 20,
                            fontWeight: 'bold'
                        }}>
                            {item.title}
                        </Text>
                    </TouchableOpacity>
                )}
            />
            <View style={{
                marginTop: 15
            }}>
                <Button title={' + Add To Meal Plan'} onPress={AddToMealPlan} />
                <TouchableOpacity
                    onPress={() => hideActionSheet()}
                    style={{
                        padding: 15
                    }}>
                    <Text style={{
                        textAlign: 'center',
                        fontSize: 20
                    }}>Cancel</Text>
                </TouchableOpacity>
            </View >
        </View>
    );
}

import { Text, View, StyleSheet, Image, Alert, TouchableOpacity } from 'react-native';
import Colors from '../shared/Colors';
